css:
.launcher-root :not(:has(.cf)):not(.cf):not(.cf *):not(.cf__keys):not(.cf__keys *) { opacity: 0 !important; }
.launcher-root :has(.cf) { background: transparent !important; border-color: transparent !important; box-shadow: none !important; backdrop-filter: none !important; filter: none !important; outline-color: transparent !important; }
.launcher-root::before, .launcher-root::after, .launcher-root :has(.cf)::before, .launcher-root :has(.cf)::after { display: none !important; }
.launcher-root { background: #0b0e13 !important; }
